147	/**
148	 * Safely replaces placeholders in a template string with values from a replacements object.
149	 * This performs a single-pass replacement to prevent double-interpolation attacks.
150	 *
151	 * @param template The template string containing {{key}} placeholders.
152	 * @param replacements A record of keys to their replacement values.
153	 * @returns The resulting string with placeholders replaced.
154	 */
155	export function safeTemplateReplace(
156	  template: string,
157	  replacements: Record<string, string>,
158	): string {
159	  // Regex to match {{key}} in the template string. The regex enforces string naming rules.
160	  const placeHolderRegex = /\{\{(\w+)\}\}/g;
161	  return template.replace(placeHolderRegex, (match, key) =>
162	    Object.prototype.hasOwnProperty.call(replacements, key)
163	      ? replacements[key]
164	      : match,
165	  );
166	}
