110	 */
111	export function parsePrompt(text: string): {
112	  validUrls: string[];
113	  errors: string[];
114	} {
115	  const tokens = text.split(/\s+/);
116	  const validUrls: string[] = [];
117	  const errors: string[] = [];
118	
119	  for (const token of tokens) {
120	    if (!token) continue;
121	
122	    // Heuristic to check if the url appears to contain URL-like chars.
123	    if (token.includes('://')) {
124	      try {
125	        // Validate with new URL()
126	        const url = new URL(token);
127	
128	        // Allowlist protocols
129	        if (['http:', 'https:'].includes(url.protocol)) {
130	          validUrls.push(url.href);
131	        } else {
132	          errors.push(
133	            `Unsupported protocol in URL: "${token}". Only http and https are supported.`,
134	          );
135	        }
136	      } catch {
137	        // new URL() threw, so it's malformed according to WHATWG standard
138	        errors.push(`Malformed URL detected: "${token}".`);
139	      }
140	    }
141	  }
142	
143	  return { validUrls, errors };
